sparql:
# Lists the named graphs of the LiITA endpoint.


SELECT DISTINCT ?graph
WHERE {
  GRAPH ?graph { ?s a ?type }
}

# This query counts the total number of Lemma resources in the main LiITA graph using OntoLex-Lemon and LILA ontology terms
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT (COUNT(?lemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

# This query explores predicates (?p) used to describe Lemma instances in the LiITA knowledge base, utilizing OntoLex-Lemon structures.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT DISTINCT ?p
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ?p ?o .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}

# This query retrieves all distinct Part-of-Speech (POS) tags used in lemmas from the LiITA knowledge base using the lila:hasPOS property.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT DISTINCT ?pos
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma lila:hasPOS ?pos .
  }
}

# This query retrieves lemmas from the LiITA knowledge base whose written representation ends with the suffix "-mente", typically indicating adverbs in Italian.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER regex(str(?italianWord), "mente$")
  }
}

# This query retrieves lemmas from the LiITA Lemma Bank whose written representations start with the prefix "anti-".
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER regex(str(?italianWord), "^anti")
  }
}

# This query retrieves very long words (potential compounds) from the LiITA Lemma Bank by selecting lemmas with written representations longer than 18 characters, ordered by string length descending.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?wr (STRLEN(str(?wr)) AS ?len)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ontolex:writtenRep ?wr .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER (STRLEN(str(?wr)) > 18)
  }
}
ORDER BY DESC(?len)

# This query retrieves lemmas from the LiITA knowledge base that have multiple written representations (variants), leveraging the OntoLex-Lemon model to count different written forms per lemma.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?lemma (COUNT(?wr) as ?variantCount)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ontolex:writtenRep ?wr .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}
GROUP BY ?lemma
HAVING (COUNT(?wr) > 1)

# Retrieves lemmas from the LiITA knowledge base whose written representation contains the substring "geo"
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER regex(str(?italianWord), "geo", "i")
  }
}

# Counts the number of lemmas classified as verbs in the LiITA Lemma Bank using the lila:hasPOS property within the LiITA data graph.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT (COUNT(?lemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma lila:hasPOS lila:verb .
  }
}

# This query retrieves up to 50 noun lemmas (their written representations) from the LiITA Lemma Bank using OntoLex-Lemon and LiLa ontologies.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma lila:hasPOS lila:noun ;
        ontolex:writtenRep ?italianWord .
  }
}

# Retrieve adjectives from the LiITA Lemma Bank whose written forms end with the suffix "-ile".
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma lila:hasPOS lila:adjective ;
        ontolex:writtenRep ?italianWord .
    FILTER regex(str(?italianWord), "ile$")
  }
}

# This query counts the total number of lemma entries in the Sicilian Lemma Bank within the LiITA knowledge base.
PREFIX dcterms: <http://purl.org/dc/terms/>

SELECT (COUNT(?lemma) AS ?count)
WHERE {
  ?lemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
}

# Retrieves Sicilian nouns from the LiITA Lemma Bank whose written form starts with "z"
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?wr
WHERE {
  ?lemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
      lila:hasPOS lila:noun ;
      ontolex:writtenRep ?wr .
  FILTER regex(str(?wr), "^z", "i")
}

# Retrieve Sicilian words from the LiITA Lemma Bank that end with the letter "u" (typical masculine ending) using OntoLex-Lemon representation
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?wr
WHERE {
  ?lemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
      ontolex:writtenRep ?wr .
  FILTER regex(str(?wr), "u$")
}

# This query retrieves the definition(s) of the Italian lemma "gatto" from the CompL-it resource in the LiITA knowledge base using OntoLex-Lemon structures.
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wrIta ] ;
        ontolex:sense [ skos:definition ?definition ] .
    FILTER ( STR(?wrIta) = "gatto" ) .
  }
}

# This query retrieves hyponyms of the Italian lemma "veicolo" from the LiITA Lemma Bank, leveraging OntoLex-Lemon semantic relations to find more specific lexical senses linked by hypernymy.
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?hyponymWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wrIta ] .
    FILTER ( STR(?wrIta) = "veicolo" ) .
    ?word ontolex:sense ?sense .
    ?sense lexinfo:hypernym ?hypoSense .  # ?sense is a hypernym of (more general than) ?hypoSense
    ?hypoWord ontolex:sense ?hypoSense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?hyponymWord ] .
  }
}

# This query retrieves Italian meronyms (parts) of the lemma "corpo" from the LiITA Lemma Bank using OntoLex-Lemon structures.
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?partWord ?sense
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wrIta ] ;
        ontolex:sense ?sense .
    FILTER( STR(?wrIta) = "corpo" ) .
    ?partSense lexinfo:partMeronym ?sense .  # ?partSense is a part of ?sense
    ?partLemma ontolex:sense ?partSense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?partWord ] .
  }
}

# This query retrieves lemmas and their definitions from the LiITA Lemma Bank where the definition contains the word "amore", using OntoLex-Lemon structures to access canonical forms and senses.
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?lemma ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?lemma ] ;
        ontolex:sense [ skos:definition ?definition ] .
    FILTER regex(?definition, "amore", "i")
  }
}

# Counts the senses of the word "piano" in CompL-it.
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT (COUNT(DISTINCT ?sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wr ] ;
        ontolex:sense ?sense .
    FILTER(STR(?wr) = "piano")
  }
}

# Lists the properties used in the ELIta graph.


SELECT DISTINCT ?graph ?p
WHERE {
  GRAPH ?graph { ?s ?p ?o }
  FILTER(CONTAINS(LCASE(STR(?graph)), "elita"))
}

# This query retrieves verbs from the LiITA Lemma Bank whose written forms end with "-ere" and orders them by ascending length.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma lila:hasPOS lila:verb ;
        ontolex:writtenRep ?italianWord .
    FILTER regex(str(?italianWord), "ere$")
  }
}
ORDER BY ASC(STRLEN(str(?italianWord)))

# This query counts the number of explicit translation relations (vartrans:translatableAs) in the LiITA Lemma Bank dataset using OntoLex-Lemon vocabulary.
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT (COUNT(*) as ?count)
WHERE {
  ?s vartrans:translatableAs ?o .
}

# This query retrieves definitions for Italian lemmas starting with "z" from the LiITA knowledge base using OntoLex structures and integrates service data from an external SPARQL endpoint.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?lemma ?definition
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        ontolex:writtenRep ?lemma .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER regex(?lemma, "^z", "i")
  }
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?lemma ] ;
        ontolex:sense [ skos:definition ?definition ] .
  }
}

# Pairs of CompL-it words whose senses are antonyms, with their definitions.
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?word1 ?wr1 ?word2 ?wr2 ?definition1 ?definition2
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word1 ontolex:sense ?sense1 ;
        ontolex:canonicalForm [ ontolex:writtenRep ?wr1 ] .
    ?sense1 lexinfo:antonym ?sense2 .
    ?word2 ontolex:sense ?sense2 ;
        ontolex:canonicalForm [ ontolex:writtenRep ?wr2 ] .
    OPTIONAL { ?sense1 skos:definition ?definition1 }
    OPTIONAL { ?sense2 skos:definition ?definition2 }
  }
}

# This query retrieves lemmas and their associated part-of-speech (PoS) tags from the LiITA knowledge base using OntoLex-Lemon and lila ontology structures.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT DISTINCT ?lemma ?pos
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma lila:hasPOS ?pos .
  }
}

# This query retrieves the count of lemmas grouped by their part of speech (PoS) in the LiITA Lemma Bank using OntoLex-Lemon and LILA ontologies.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT ?pos (COUNT(?lemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma lila:hasPOS ?pos .
  }
}
GROUP BY ?pos
ORDER BY DESC(?count)

# This query retrieves up to 10 lemmas from the LiITA knowledge base whose canonical written form ends with the suffix "-zione".
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?lemma ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma ontolex:writtenRep ?italianWord .
    FILTER (regex(str(?italianWord), "zione$"))
  }
}

# Retrieve up to 10 lemmas from the LiITA knowledge base whose written representations start with the prefix 'pre' (case-insensitive), leveraging OntoLex-Lemon ontology.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?lemma ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma ontolex:writtenRep ?italianWord .
    FILTER (regex(str(?italianWord), "^pre", "i"))
  }
}

# Query to retrieve verbs from the LiITA Lemma Bank where the canonical form contains the substring "auto", using OntoLex-Lemon structures for lemmas and their written representations.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?lemma ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma lila:hasPOS lila:verb .
    ?lemma ontolex:writtenRep ?italianWord .
    FILTER regex(str(?italianWord), "auto", "i")
  }
}

# Counts the Italian lemmas that have at least one Sicilian translation.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT (COUNT(DISTINCT ?italianLemma) AS ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?italianEntry ontolex:canonicalForm ?italianLemma ;
      vartrans:translatableAs ?sicilianEntry .
  ?sicilianEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> .
}

# This query computes the average number of distinct written forms per lemma for each part of speech (PoS) in the LiITA Lemma Bank using OntoLex-Lemon vocabulary.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?pos (AVG(?formCount) AS ?avgForms)
WHERE {
  GRAPH <http://liita.it/data> {
    {
      SELECT ?lemma ?pos (COUNT(DISTINCT ?wr) AS ?formCount)
      WHERE {
        ?lemma a ?lemmaType ;
            lila:hasPOS ?pos ;
            ontolex:writtenRep ?wr .
        FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
      } GROUP BY ?lemma ?pos
    }
  }
}
GROUP BY ?pos

# This query retrieves Italian lemmas from the LiITA Lemma Bank that do NOT have any Sicilian (or other dialect) translation recorded, using OntoLex-Lemon and vartrans vocabularies.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?lemma ?wr
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        ontolex:writtenRep ?wr .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    FILTER NOT EXISTS {
      ?entry ontolex:canonicalForm ?lemma .
      ?entry vartrans:translatableAs ?dialectLexEntry .
    }
  }
}

# This query retrieves lemmas from the LiITA knowledge base whose spelled forms (written representations) contain accented Italian characters, using OntoLex-Lemon vocabulary.
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?lemma ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma ontolex:writtenRep ?italianWord .
    FILTER regex(str(?italianWord), "[àèéìòóùÀÈÉÌÒÓÙ]")
  }
}

# This query retrieves nouns from the LiITA Lemma Bank that have more than one distinct written form, indicating multiple inflectional variants such as singular and plural.
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?lemma (GROUP_CONCAT(DISTINCT ?italianWord; separator=", ") AS ?forms)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType ;
        lila:hasPOS lila:noun ;
        ontolex:writtenRep ?italianWord .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
  }
}
GROUP BY ?lemma
HAVING (COUNT(DISTINCT ?italianWord) > 1)
LIMIT 10

# This query retrieves distinct lemmas and their written representations from the LiITA Lemma Bank that are in the semantic domain of 'color' based on CompL-it definitions containing specific color-related terms, using OntoLex-Lemon structures and a remote SPARQL service.
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?lemma ?wr
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word a ontolex:Word ;
        ontolex:canonicalForm ?lemma ;
        ontolex:sense ?sense .
    ?sense skos:definition ?definition .
    FILTER regex(str(?definition), "colore|colorato|colori", "i")
    ?lemma ontolex:writtenRep ?wr .
  }
}

# This query retrieves highly positive expressions from the ELITA dataset in the LiITA knowledge base, obtains their emotions, and enriches them with dictionary senses and definitions of the corresponding Italian nouns using OntoLex-Lemon structures.
PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT
?emotionLexEntry ?lexEntryLabel
?emotionLabel
?polarity ?polarityValue
?sense ?definition
WHERE {
  GRAPH <http://w3id.org/elita> {
    ?emotionLexEntry elita:HasEmotion ?emotion ;
        rdfs:label ?lexEntryLabel ;
        marl:Polarity ?polarity ;
        marl:hasPolarityValue ?polarityValue ;
        ontolex:canonicalForm ?cf .
    ?emotionResource rdfs:label ?emotionLabel .
    FILTER(?polarityValue > 0.7)
  }
  ?cf ontolex:writtenRep ?lemma .
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word a ontolex:Word ;
        lexinfo:partOfSpeech [ rdfs:label ?pos ] ;
        ontolex:sense ?sense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?lemma ] .
    ?sense skos:definition ?definition .
    FILTER(str(?pos) = "noun")
  }
}

# This query retrieves expressions from the LiITA Lemma Bank that convey strong positive emotions, along with their meanings, polarity values, and dictionary senses, highlighting senses whose definitions or labels explicitly mention the same emotion and ranking accordingly.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT
?emotionLexEntry
?lexEntryLabel
?emotionLabel
?polarity
?polarityValue
?lemma
?sense
?senseLabel
?definition
?sensePOS
?senseLexicon
( (IF(bound(?senseLabel) && CONTAINS(LCASE(STR(?senseLabel)), LCASE(STR(?emotionLabel))), 1, 0)
+ IF(bound(?definition) && CONTAINS(LCASE(STR(?definition)), LCASE(STR(?emotionLabel))), 1, 0)) AS ?score )
WHERE {
  GRAPH <http://w3id.org/elita> {
    ?emotionLexEntry elita:HasEmotion ?emotion ;
        rdfs:label ?lexEntryLabel ;
        marl:Polarity ?polarity ;
        marl:hasPolarityValue ?polarityValue ;
        ontolex:canonicalForm ?cf .
    ?emotion rdfs:label ?emotionLabel .
    FILTER(?polarityValue > 0.7)
  }
  ?cf ontolex:writtenRep ?lemma .
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word a ?wType ;
        ontolex:canonicalForm [ ontolex:writtenRep ?lemma ] .
    ?word (ontolex:sense|ontolex:evokes) ?sense .
    OPTIONAL { ?sense rdfs:label ?senseLabel . }
    OPTIONAL { ?sense skos:definition ?definition . }
    OPTIONAL { ?sense rdfs:comment ?senseComment . }
    OPTIONAL { ?word lexinfo:partOfSpeech [ rdfs:label ?sensePOS ] . }
    OPTIONAL { ?word dcterms:isPartOf ?senseLexicon . }
  }
}
ORDER BY DESC(?score) DESC(?polarityValue)

# Parts (meronyms) of "albero" in CompL-it, with their definitions.
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?partWord ?partWr ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?wholeWord ontolex:canonicalForm [ ontolex:writtenRep ?wholeWr ] ;
        lexinfo:partOfSpeech [ rdfs:label ?partOfSpeech ] ;
        ontolex:sense ?wholeSense .
    FILTER(STR(?wholeWr) = "albero" && STR(?partOfSpeech) = "noun")
    ?partSense lexinfo:partMeronym ?wholeSense .  # ?partSense is a part of ?wholeSense
    ?partWord ontolex:sense ?partSense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?partWr ] .
    OPTIONAL { ?partSense skos:definition ?definition }
  }
}

# Wholes that "braccio" is a part of (holonyms) in CompL-it.
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?wholeWord ?wholeWr ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?partWord ontolex:canonicalForm [ ontolex:writtenRep ?partWr ] ;
        lexinfo:partOfSpeech [ rdfs:label ?partOfSpeech ] ;
        ontolex:sense ?partSense .
    FILTER(STR(?partWr) = "braccio" && STR(?partOfSpeech) = "noun")
    ?partSense lexinfo:partMeronym ?wholeSense .  # ?partSense is a part of ?wholeSense
    ?wholeWord ontolex:sense ?wholeSense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?wholeWr ] .
    OPTIONAL { ?wholeSense skos:definition ?definition }
  }
}

