# This query retrieves all senses of the Italian lemma 'piano' from the LiITA knowledge base, including their definitions, examples, and labels using OntoLex-Lemon structures.
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?sense ?definition ?example ?label
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wrIta ] .
    FILTER ( STR(?wrIta) = "piano" ) .
    ?word ontolex:sense ?sense .
    OPTIONAL { ?sense skos:definition ?definition }
    OPTIONAL { ?sense skos:example ?example }
    OPTIONAL { ?sense rdfs:label ?label }
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT ?pos (COUNT(*) as ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma lila:hasPOS ?pos .
  }
}
GROUP BY ?pos
ORDER BY DESC (?count )

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT COUNT(*) as ?count
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma lila:hasPOS lila:noun .
    ?lemma ontolex:writtenRep ?wr .
    FILTER regex(str(?wr), "ione$") .
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT DISTINCT ?lemma ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a ?lemmaType .
    FILTER(?lemmaType IN (lila:Lemma, lila:Hypolemma))
    ?lemma ontolex:writtenRep ?italianWord .
    FILTER regex(str(?italianWord), "^infra") .
  }
}

# Nouns whose CompL-it definition starts with "uccello", with their Parmigiano translations.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?definition ?parmigianoWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word lexinfo:partOfSpeech [ rdfs:label ?pos ] ;
        ontolex:sense ?sense .
    ?sense skos:definition ?definition .
    FILTER(STR(?pos) = "noun" && STRSTARTS(STR(?definition), "uccello"))
  }
  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?italianEntry ontolex:canonicalForm ?italianLemma ;
      vartrans:translatableAs ?parmigianoEntry .
  ?parmigianoEntry ontolex:canonicalForm ?parmigianoLemma .
  ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
      ontolex:writtenRep ?parmigianoWord .
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?senseHyponym (GROUP_CONCAT(str(?definition);SEPARATOR="; esempio: ") AS ?definition) ?italianLemma ?parmigianoLemma ?wr
WHERE
{
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word a ontolex:Word ;
        lexinfo:partOfSpeech [ rdfs:label ?pos ] ;
        ontolex:sense ?sense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?lemma ] .
    ?sense lexinfo:hypernym ?senseHyponym .  # ?sense is a hypernym of (more general than) ?senseHyponym
    OPTIONAL {
      ?senseHyponym skos:definition ?definition
    } .
    FILTER(str(?pos) = "noun") .
    FILTER(str(?lemma) = "colore") .
    ?wordHyponym ontolex:sense ?senseHyponym .
  }
  ?wordHyponym ontolex:canonicalForm ?italianLemma.
  ?italianLexEntry ontolex:canonicalForm ?italianLemma;
      ^lime:entry <http://liita.it/data/id/LexicalReources/DialettoParmigiano/Lexicon>.
  ?italianLexEntry vartrans:translatableAs ?parmigianoLexEntry.
  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma.
  ?parmigianoLemma ontolex:writtenRep ?parmigianoWord
}
GROUP BY ?senseHyponym ?italianLemma ?parmigianoLemma ?wr
ORDER BY ASC(?wr)

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?senseMeronym (GROUP_CONCAT(str(?definition);SEPARATOR="; esempio: ") AS ?definition) ?italianLemma ?parmigianoLemma ?wr
WHERE
{
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word a ontolex:Word ;
        lexinfo:partOfSpeech [ rdfs:label ?pos ] ;
        ontolex:sense ?sense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?lemma ] .
    ?senseMeronym lexinfo:partMeronym ?sense .  # ?senseMeronym is a part of ?sense
    OPTIONAL {
      ?senseMeronym skos:definition ?definition
    } .
    FILTER(str(?pos) = "noun") .
    FILTER(str(?lemma) = "giorno") .
    ?wordMeronym ontolex:sense ?senseMeronym .
  }
  ?wordMeronym ontolex:canonicalForm ?italianLemma.
  ?italianLexEntry ontolex:canonicalForm ?italianLemma;
      ^lime:entry <http://liita.it/data/id/LexicalReources/DialettoParmigiano/Lexicon>.
  ?italianLexEntry vartrans:translatableAs ?parmigianoLexEntry.
  ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma.
  ?parmigianoLemma ontolex:writtenRep ?parmigianoWord
}
GROUP BY ?senseMeronym ?italianLemma ?parmigianoLemma ?wr
ORDER BY ASC(?wr)

# Hyponyms of "sentimento" (CompL-it) associated with Gioia (ELIta), with their Sicilian translations.
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?sicilianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?seed ontolex:canonicalForm [ ontolex:writtenRep ?seedWr ] ;
        ontolex:sense ?seedSense .
    FILTER(STR(?seedWr) = "sentimento")
    ?hyponymSense lexinfo:hyponym ?seedSense .  # ?hyponymSense is a hyponym of (more specific than) ?seedSense
    ?hyponymWord ontolex:sense ?hyponymSense .
  }
  ?hyponymWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?emotionEntry ontolex:canonicalForm ?italianLemma ;
      elita:HasEmotion elita:Gioia .
  ?italianEntry ontolex:canonicalForm ?italianLemma ;
      vartrans:translatableAs ?sicilianEntry .
  ?sicilianEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
      ontolex:writtenRep ?sicilianWord .
}

# Parts of "corpo" (CompL-it) with their ELIta emotions and Sentix polarity values.
PREFIX elita: <http://w3id.org/elita/>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?italianWord ?emotion ?emotionLabel ?polarityValue
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?whole ontolex:canonicalForm [ ontolex:writtenRep ?wholeWr ] ;
        ontolex:sense ?wholeSense .
    FILTER(STR(?wholeWr) = "corpo")
    ?partSense lexinfo:partMeronym ?wholeSense .  # ?partSense is a part of ?wholeSense
    ?partWord ontolex:sense ?partSense .
  }
  ?partWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?emotionEntry ontolex:canonicalForm ?italianLemma ;
      elita:HasEmotion ?emotion .
  ?emotion rdfs:label ?emotionLabel .
  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
      marl:hasPolarityValue ?polarityValue .
}

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?definition ?emotionLabel ?polarityValue ?sicilianWord
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:sense ?sense ;
        ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
    ?sense skos:definition ?definition .
    FILTER(REGEX(STR(?writtenRep), "^paur", "i"))
  }
  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a ?italianLemmaType ;
        lila:hasPOS lila:noun ;
        ontolex:writtenRep ?italianWord .
    FILTER(?italianLemmaType IN (lila:Lemma, lila:Hypolemma))
  }
  ?emotionEntry ontolex:canonicalForm ?italianLemma .
  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }
  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
      marl:hasPolarity ?polarity ;
      marl:hasPolarityValue ?polarityValue .
  ?sicilianEntry ontolex:canonicalForm ?italianLemma ;
      vartrans:translatableAs ?sicilianLexEntry .
  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
      ontolex:writtenRep ?sicilianWord .
}
